import{_ as e,o as r,c as o,a3 as n}from"./chunks/framework.Ki30n65y.js";const h=JSON.parse('{"title":"Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"reference/glossary.md","filePath":"reference/glossary.md"}'),s={name:"reference/glossary.md"};function a(d,t,i,c,g,l){return r(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Approval</strong></td><td>An exception scoped to one policy, created from the Monitoring page. Only that policy stops matching the package.</td></tr><tr><td><strong>Artifact cache</strong></td><td>Package files from public registries kept on each DepGate replica&#39;s local disk.</td></tr><tr><td><strong>Audit Log</strong></td><td>The record of every change a person made in DepGate, every sign-in and every package check.</td></tr><tr><td><strong>CI token</strong></td><td>A download-only token minted by a service account for one pipeline job. It lasts at most 1 day.</td></tr><tr><td><strong>CVSS</strong></td><td>Common Vulnerability Scoring System. A 0–10 severity score: Medium from 4.0, High from 7.0, Critical from 9.0.</td></tr><tr><td><strong>Decision Ledger</strong></td><td>The record of every download DepGate refused, and why.</td></tr><tr><td><strong>Dependency confusion</strong></td><td>An attack in which a public package impersonates an internal package name. Prevented by namespace protection.</td></tr><tr><td><strong>Ecosystem</strong></td><td>A package format and its clients: npm, PyPI, Maven, Go, NuGet, Cargo, Composer or RubyGems.</td></tr><tr><td><strong>Enforce</strong></td><td>A policy mode in which matching versions are blocked.</td></tr><tr><td><strong>EPSS</strong></td><td>Exploit Prediction Scoring System, from FIRST. The daily probability that a CVE will be exploited in the next 30 days.</td></tr><tr><td><strong>Exception</strong></td><td>A time-bound permission for a package that policies would block.</td></tr><tr><td><strong>Identity provider</strong></td><td>The OpenID Connect or SAML service people sign in with when single sign-on is set up.</td></tr><tr><td><strong>Internal registry</strong></td><td>A remote repository that holds your organization&#39;s own packages.</td></tr><tr><td><strong>Log streaming</strong></td><td>Delivery of DepGate&#39;s events in batches to a SIEM or log platform.</td></tr><tr><td><strong>Malware list</strong></td><td>Known-malicious packages, from the synced threat feed and your own entries.</td></tr><tr><td><strong>Monitor mode</strong></td><td>A policy mode that records what would be blocked, without blocking.</td></tr><tr><td><strong>Namespace protection</strong></td><td>A rule that serves your internal package names only from trusted remotes.</td></tr><tr><td><strong>OSV</strong></td><td>Open Source Vulnerabilities, the vulnerability database DepGate uses.</td></tr><tr><td><strong>Package check</strong></td><td>The page and API that show which versions of a package are allowed, and why.</td></tr><tr><td><strong>Policy</strong></td><td>A rule plus an action (Block or Allow), with a priority, an ecosystem and a repository scope.</td></tr><tr><td><strong>Priority</strong></td><td>The order of policy evaluation. Lower numbers first; the first match decides.</td></tr><tr><td><strong>Registry token</strong></td><td>The personal token in a developer&#39;s package manager settings.</td></tr><tr><td><strong>Remote repository</strong></td><td>A repository that proxies one upstream registry.</td></tr><tr><td><strong>Scorecard</strong></td><td>The OpenSSF Scorecard, a 0–10 rating of an open-source project&#39;s security practices.</td></tr><tr><td><strong>Service account</strong></td><td>A non-interactive account whose key mints CI tokens.</td></tr><tr><td><strong>Virtual repository</strong></td><td>A repository that serves several remotes behind one URL, asking them in order.</td></tr><tr><td><strong>Waiver request</strong></td><td>A developer&#39;s request for an exception, reviewed by the security team.</td></tr></tbody></table>',2)])])}const y=e(s,[["render",a]]);export{h as __pageData,y as default};
